import React, { useState } from "react";

const quizData = [
  { question: "What is recursion?", options: ["Loop", "Self-calling function", "Database", "None"], answer: "Self-calling function" },
  { question: "Which sorting algorithm uses divide and conquer?", options: ["QuickSort", "BubbleSort", "SelectionSort", "InsertionSort"], answer: "QuickSort" },
];

const Quiz = () => {
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState(null);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);

  const handleNext = () => {
    if (selected === quizData[index].answer) {
      setScore(score + 1);
    }
    setSelected(null);

    if (index + 1 < quizData.length) {
      setIndex(index + 1);
    } else {
      setFinished(true); // Quiz finished
    }
  };

  return (
    <div className="quiz-container">
      {finished ? (
        <h3>Quiz Over! Your score: {score}/{quizData.length}</h3>
      ) : (
        <>
          <h3>{quizData[index].question}</h3>
          {quizData[index].options.map((option, i) => (
            <button
              key={i}
              className={selected === option ? "selected" : ""}
              onClick={() => setSelected(option)}
            >
              {option}
            </button>
          ))}
          <button onClick={handleNext} disabled={!selected}>Next</button>
        </>
      )}
    </div>
  );
};

export default Quiz;
